"""Build original companion material. The supplied book is NOT a build input.

References were read from the user's 2022 edition. No PDF/OCR/scan is published.
The executable data is standalone, with no network, framework or eval dependency.
"""
import json, math
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
OUT = ROOT / 'geometry-pogorelov/textbook'
units = []

def unit(n, title, pages, points, rules, pitfall):
    u = dict(id=n, grade=7 if n<=5 else 8 if n<=10 else 9, title=title,
             pages=pages, points=points, rules=rules, pitfall=pitfall, tasks=[])
    units.append(u)
    return u

def num(prompt, value, hint, explain, **extra):
    return dict(prompt=prompt, value=value, hint=hint, explain=explain, **extra)

def choice(prompt, correct, others, hint, explain):
    # Stable permutation, not a universal first-button answer.
    options=[correct]+others
    shift=sum(map(ord,prompt))%len(options)
    options=options[shift:]+options[:shift]
    return dict(prompt=prompt, value=correct, options=options, hint=hint, explain=explain)

def model(points, lines, *, circles=None, labels=None, caption=None, polygons=None, axes=False, decorations=None):
    return dict(points=points, lines=lines, circles=circles or [], labels=labels or [],
                polygons=polygons or [], axes=axes, decorations=decorations or [],
                caption=caption or 'Авторская схема к задаче. Длины и углы определяем по условию и свойствам, а не измерением экрана.')

def line(a,b,stage=0,**kw): return dict(a=a,b=b,stage=stage,**kw)
def point(x,y,stage=0): return dict(x=x,y=y,stage=stage)
def label(x,y,text,stage=0): return dict(x=x,y=y,text=text,stage=stage)

def segment(a,b,names=('C','M','D')):
    x,y,z=names
    return model({x:point(0,0),y:point(a,0),z:point(a+b,0)},[line(x,y),line(y,z)])

def tri(a=5,b=6,c=7,names=('A','B','C')):
    # a=BC, b=AC, c=AB.
    A,B,C=names; x=(b*b+c*c-a*a)/(2*c); y=math.sqrt(max(0,b*b-x*x))
    return model({A:point(0,0),B:point(c,0),C:point(x,y)},[line(A,B),line(B,C),line(C,A)])

def angles(A=50,B=60,names=('A','B','C')):
    C=180-A-B
    return tri(math.sin(math.radians(A))*8,math.sin(math.radians(B))*8,math.sin(math.radians(C))*8,names)

def cross(theta=50):
    r=math.radians(theta)
    return model({'O':point(0,0),'A':point(-4,0),'B':point(4,0),
                  'C':point(-3*math.cos(r),-3*math.sin(r)), 'D':point(3*math.cos(r),3*math.sin(r))},
                 [line('A','B'),line('C','D')])

def rays(degrees, names=None):
    ns=names or [chr(65+i) for i in range(len(degrees))]
    p={'O':point(0,0)}
    for n,d in zip(ns,degrees):p[n]=point(4*math.cos(math.radians(d)),4*math.sin(math.radians(d)))
    return model(p,[line('O',n) for n in ns])

def para(a=6,b=4,angle=65):
    dx=b*math.cos(math.radians(angle));dy=b*math.sin(math.radians(angle))
    return model({'A':point(0,0),'B':point(dx,dy),'C':point(dx+a,dy),'D':point(a,0)},
                 [line('A','B'),line('B','C'),line('C','D'),line('D','A')])

def rect(a=6,b=4):return para(a,b,90)

def circle_scene(r=3):
    return model({'O':point(0,0),'A':point(r,0)},[line('O','A')],circles=[dict(x=0,y=0,r=r,stage=0)])

def coordinate(points, lines=None):
    return model({k:point(*v) for k,v in points.items()},lines or [],axes=True,
                 caption='Авторская координатная модель. Масштаб по обеим осям одинаковый.')

def poly(n=6,r=4):
    p={chr(65+i):point(r*math.cos(math.pi/2+2*math.pi*i/n),r*math.sin(math.pi/2+2*math.pi*i/n)) for i in range(n)}
    return model(p,[line(chr(65+i),chr(65+(i+1)%n)) for i in range(n)])

def prism(a=5,b=3,c=4):
    p={'A':point(0,0),'B':point(a,0),'C':point(a+b*.6,b*.45),'D':point(b*.6,b*.45),
       'A₁':point(0,c),'B₁':point(a,c),'C₁':point(a+b*.6,b*.45+c),'D₁':point(b*.6,b*.45+c)}
    es=[line(*e, dashed=e in [('A','D'),('D','C'),('D','D₁')]) for e in
        [('A','B'),('B','C'),('D','C'),('A','D'),('A₁','B₁'),('B₁','C₁'),('C₁','D₁'),('D₁','A₁'),('A','A₁'),('B','B₁'),('C','C₁'),('D','D₁')]]
    return model(p,es,caption='Авторское изображение тела в пространстве. Пунктир — невидимые рёбра. Пространственные углы нельзя измерять на плоском рисунке.')

def add(u,no,part,page,title,goal,visual,steps,answers=None,checks=None,notes=''):
    part=str(part) if part else ''
    tid=f'p{u["id"]}-n{no}'+('-'+part.replace('(','').replace(')','').replace(' ','-').replace(',','-') if part else '')
    t=dict(id=tid,number=no,part=part,page=page,title=title,goal=goal,model=visual,steps=steps,notes=notes)
    if answers:t['answers']=[dict(label=k,value=v,**(extra or {})) for k,v,*rest in answers for extra in [rest[0] if rest else {}]]
    else:t['checks']=checks or ['Указаны исходные данные и требуемый вывод.','Каждый переход опирается на условие, определение или теорему.','Записан вывод именно для этой задачи.']
    u['tasks'].append(t)
    return t

