def midtriangle(a,b,c):
    v=tri(a,b,c)
    for name,pair in [('M',('A','B')),('N',('B','C')),('K',('C','A'))]:
        p,q=(v['points'][x] for x in pair);v['points'][name]=point((p['x']+q['x'])/2,(p['y']+q['y'])/2,1)
    v['lines'] += [line('M','N',1),line('N','K',1),line('K','M',1)]
    return v
