def similar_pair(a,b,c,k):
    v=tri(a,b,c)
    p=tri(a*k,b*k,c*k,('A₁','B₁','C₁'))
    offset=c+max(a,b,c)*.6
    for name,q in p['points'].items():q['x']+=offset
    v['points'].update(p['points']);v['lines']+=p['lines']
    return v

