def inner_parallel(ab,ac,ratio):
    v=tri(ab*.9,ac,ab)
    A,B,C=(v['points'][k] for k in ['A','B','C'])
    v['points']['D']=point(B['x']+(A['x']-B['x'])*ratio,B['y']+(A['y']-B['y'])*ratio)
    v['points']['E']=point(B['x']+(C['x']-B['x'])*ratio,B['y']+(C['y']-B['y'])*ratio)
    v['lines'].append(line('D','E'))
    return v
